#[test]
fn arm_decodes_the_encoding_tests() {
    let mut wrong = Vec::new();
    for (name, word, text) in CASES {
        let got = decode_word(*word).map(|ins| format(&ins));
        if got.as_deref() != Some(*text) {
            wrong.push(format!(
                "{}: 0x{:08x} expected {:?}, got {:?}",
                name, word, text, got
            ));
        }
    }
    assert!(
        wrong.is_empty(),
        "{} of {} cases:\n{}",
        wrong.len(),
        CASES.len(),
        wrong.join("\n")
    );
}
